def pipe(data, *funcs):
    """ Pipe a value through a sequence of functions

    I.e. ``pipe(data, f, g, h)`` is equivalent to ``h(g(f(data)))``
    """
    for func in funcs:
        data = func(data)
    return data

def compose(*funcs):
    """ Compose functions to operate in series.

    Functions are applied from right to left so that
    ``compose(f, g, h)(x, y)`` is the same as ``f(g(h(x, y)))``.
    """
    if not funcs:
        return identity
    if len(funcs) == 1:
        return funcs[0]
    else:
        return Compose(*funcs)

def thread_first(val, *forms):
    """ Thread value through a sequence of functions/forms

    So in general
        thread_first(x, f, (g, y, z))
    expands to
        g(f(x), y, z)
    """
    def evalform_front(val, form):
        if callable(form):
            return form(val)
        if isinstance(form, tuple):
            func, args = form[0], form[1:]
            args = (val,) + args
            return func(*args)
    return reduce(evalform_front, forms, val)

def preprocess(self, source, name=None, filename=None) -> str:
    return reduce(
        lambda s, e: e.preprocess(s, name, filename),
        self.iter_extensions(),
        str(source),
    )

def _tokenize(self, source, name, filename=None, state=None) -> TokenStream:
    source = self.preprocess(source, name, filename)
    stream = self.lexer.tokenize(source, name, filename, state)
    for ext in self.iter_extensions():
        stream = ext.filter_stream(stream)
        if not isinstance(stream, TokenStream):
            stream = TokenStream(stream, name, filename)
    return stream

