class PathMatches(Matcher):
    def __init__(self, pattern):
        if isinstance(pattern, str):
            pattern = re.compile(pattern)
        self.regex = pattern
    def match(self, request):
        match = self.regex.match(request.path)
        if match is None:
            return None
        return {"path_args": [match.groups()], "path_kwargs": match.groupdict()}

class Cipher(typing.Generic[Mode]):
    def __init__(self, algorithm: CipherAlgorithm, mode: Mode, backend: typing.Any = None) -> None:
        if not isinstance(algorithm, CipherAlgorithm):
            raise TypeError("Expected interface of CipherAlgorithm.")
        if mode is not None:
            assert isinstance(mode, modes.Mode)
            mode.validate_for_algorithm(algorithm)
        self.algorithm = algorithm
        self.mode = mode

    def encryptor(self):
        if isinstance(self.mode, modes.ModeWithAuthenticationTag):
            if self.mode.tag is not None:
                raise ValueError("Authentication tag must be None when encrypting.")
        return rust_openssl.ciphers.create_encryption_ctx(self.algorithm, self.mode)

