class CallbackRegistry:
    def __init__(self, exception_handler=_exception_printer, *, signals=None):
        self._signals = None if signals is None else list(signals)
        self.exception_handler = exception_handler
        self.callbacks = {}
        self._cid_gen = itertools.count()

    def connect(self, signal, func):
        if self._signals is not None:
            _api.check_in_list(self._signals, signal=signal)
        proxy = _weak_or_strong_ref(func, functools.partial(self._remove_proxy, signal))
        cid = self._func_cid_map[signal, proxy] = next(self._cid_gen)
        self.callbacks.setdefault(signal, {})[cid] = proxy
        return cid

    def process(self, s, *args, **kwargs):
        for ref in list(self.callbacks.get(s, {}).values()):
            func = ref()
            if func is not None:
                try:
                    func(*args, **kwargs)
                except Exception as exc:
                    if self.exception_handler is not None:
                        self.exception_handler(exc)
                    else:
                        raise

class Signature(dict):
    TYPES = {}

    @classmethod
    def register_type(cls, name=None):
        def _inner(subclass):
            cls.TYPES[name or subclass.__name__] = subclass
            return subclass
        return _inner

    @classmethod
    def from_dict(cls, d, app=None):
        typ = d.get('subtask_type')
        if typ:
            target_cls = cls.TYPES[typ]
            if target_cls is not cls:
                return target_cls.from_dict(d, app=app)
        return Signature(d, app=app)

    def __or__(self, other):
        if isinstance(other, _chain):
            return _chain(seq_concat_seq((self,), other.unchain_tasks()), app=self._app)
        elif isinstance(other, group):
            other = maybe_unroll_group(other)
            return _chain(self, other, app=self.app)
        elif isinstance(other, Signature):
            return _chain(self, other, app=self._app)
        return NotImplemented

