    return cast(Fn, _wrapper)

class MarkGenerator:
    def __getattr__(self, name: str) -> MarkDecorator:
        """Generate a new MarkDecorator with the given name."""
        if name[0] == "_":
            raise AttributeError("Marker name must NOT start with underscore")
        if self._config is not None:
            if name not in self._markers:
                for line in self._config.getini("markers"):
                    marker = line.split(":")[0].split("(")[0].strip()
                    self._markers.add(marker)
            if name not in self._markers:
                if self._config.option.strict_markers:
                    fail(f"{name!r} not found in `markers` configuration option")
                warnings.warn(f"Unknown pytest.mark.{name} - is this a typo?")
        return MarkDecorator(Mark(name, (), {}, _ispytest=True), _ispytest=True)

def __getattr__(self, name: str) -> Any:
    if name not in self.__kwargs:
        raise AttributeError(f"No attribute {name}")
    if not hasattr(self.__threadlocal, name):
        default = self.__kwargs[name]()
        setattr(self.__threadlocal, name, default)
    return getattr(self.__threadlocal, name)

