@frozen(repr=False)
class TypeChecker:
    _type_checkers: HashTrieMap = field(default=HashTrieMap(), converter=_typed_map_converter)

    def redefine(self, type, fn) -> TypeChecker:
        return self.redefine_many({type: fn})

    def redefine_many(self, definitions=()) -> TypeChecker:
        type_checkers = self._type_checkers.update(definitions)
        return evolve(self, type_checkers=type_checkers)

    def remove(self, *types) -> TypeChecker:
        type_checkers = self._type_checkers
        for each in types:
            type_checkers = type_checkers.remove(each)
        return evolve(self, type_checkers=type_checkers)

class Session(SessionRedirectMixin):
    def get_adapter(self, url: str) -> BaseAdapter:
        for prefix, adapter in self.adapters.items():
            if url.lower().startswith(prefix.lower()):
                return adapter
        raise InvalidSchema(f"No connection adapters were found for {url!r}")

    def mount(self, prefix: str, adapter: BaseAdapter) -> None:
        self.adapters[prefix] = adapter
        keys_to_move = [k for k in self.adapters if len(k) < len(prefix)]
        for key in keys_to_move:
            self.adapters[key] = self.adapters.pop(key)

def as_connectable(remote, /, *, tls=False, ssl_context=None, ...):
    if isinstance(remote, ByteStreamConnectable):
        return remote
    elif isinstance(remote, tuple) and len(remote) == 2:
        connectable = TCPConnectable(*remote)
    elif isinstance(remote, (str, bytes, PathLike)):
        connectable = UNIXConnectable(remote)
    else:
        raise TypeError(f"cannot convert {remote!r} to a connectable")
    if tls:
        connectable = TLSConnectable(connectable, ...)

