class CapacityLimiter(BaseCapacityLimiter):
    __slots__ = "_total_tokens", "_borrowers", "_wait_queue"

    def __init__(self, total_tokens: float):
        self._total_tokens: float = 0
        self._borrowers: set[Any] = set()
        self._wait_queue: OrderedDict[Any, asyncio.Event] = OrderedDict()
        self.total_tokens = total_tokens

    @total_tokens.setter
    def total_tokens(self, value: float) -> None:
        waiters_to_notify = max(value - self._total_tokens, 0)
        self._total_tokens = value
        while self._wait_queue and waiters_to_notify:
            borrower, event = self._wait_queue.popitem(last=False)
            self._borrowers.add(borrower)
            event.set()
            waiters_to_notify -= 1

    def acquire_on_behalf_of_nowait(self, borrower: object) -> None:
        if borrower in self._borrowers:
            raise RuntimeError("this borrower is already holding one of this CapacityLimiter's tokens")
        if self._wait_queue or len(self._borrowers) >= self._total_tokens:
            raise WouldBlock
        self._borrowers.add(borrower)

