class SearchStrategy(Generic[Ex]):
    def map(self, pack: Callable[[Ex], T]) -> "SearchStrategy[T]":
        if is_identity_function(pack):
            return self
        return MappedStrategy(self, pack=pack)

    def flatmap(self, expand: Callable[[Ex], "SearchStrategy[T]"]) -> "SearchStrategy[T]":
        from hypothesis.strategies._internal.flatmapped import FlatMapStrategy
        return FlatMapStrategy(self, expand=expand)

    def filter(self, condition):
        return FilteredStrategy(self, conditions=(condition,))

    def __or__(self, other: "SearchStrategy[T]") -> "SearchStrategy[Ex | T]":
        strategies: list[SearchStrategy] = []
        strategies.extend(
            self.original_strategies if isinstance(self, OneOfStrategy) else [self]
        )
        strategies.extend(
            other.original_strategies if isinstance(other, OneOfStrategy) else [other]
        )
        return OneOfStrategy(strategies)

def given(
    *_given_arguments: SearchStrategy[Any] | EllipsisType,
    **_given_kwargs: SearchStrategy[Any] | EllipsisType,
) -> Callable[[Callable[..., Coroutine[Any, Any, None] | None]], Callable[..., None]]:
    def run_test_as_given(test):
        original_sig = get_signature(test)
        given_kwargs = dict(_given_kwargs)
        new_signature = new_given_signature(original_sig, given_kwargs)
        # type inference for ... (infer) arguments
        if ... in given_kwargs.values():
            hints = get_type_hints(test)
        for name in [name for name, value in given_kwargs.items() if value is ...]:
            given_kwargs[name] = st.from_type(hints[name])

        @impersonate(test)
        @define_function_signature(test.__name__, test.__doc__, new_signature)
        def wrapped_test(*arguments, **kwargs):
            __tracebackhide__ = True
            state = StateForActualGivenExecution(stuff, test, settings, random, wrapped_test, ...)
            state.run_engine()
            return state.report_data

        wrapped_test.hypothesis = HypothesisHandle(test, ...)
        return wrapped_test
    return run_test_as_given

def recursive_property(strategy: "SearchStrategy", name: str, default: object) -> Any:
    # First pass: direct recursive calculation with blocking
    def recur(strat):
        result = mapping.get(strat, sentinel)
        if result is calculating:
            hit_recursion = True
            return default
        elif result is sentinel:
            mapping[strat] = calculating
            mapping[strat] = getattr(strat, calculation)(recur)
            return mapping[strat]
        return result
    recur(strategy)

    # If self-recursion hit, do careful fixed point
    if hit_recursion:
        while needs_update:
            to_update = needs_update
            needs_update = set()
            for strat in to_update:
                new_value = getattr(strat, calculation)(recur2(strat))
                if new_value != mapping[strat]:
                    needs_update.update(listeners[strat])
                    mapping[strat] = new_value

    for k, v in mapping.items():
        setattr(k, cache_key, v)
    return forced_or_cached_value(strategy)

