class Shrinker:
    def __init__(self, engine, initial, predicate, *, allow_transition=None):
        self.engine = engine
        self.shrink_target = initial
        self.predicate = predicate
        self.shrinks = 0
        self.passes = []  # list of (name, pass_fn)

    def shrink(self):
        while self.single_greedy_shrink_pass():
            pass  # run until no pass makes progress

    def single_greedy_shrink_pass(self):
        ran_at_least_one = False
        for name, pass_fn in self.passes:
            ran_at_least_one = True
            initial_shrinks = self.shrinks
            pass_fn(self)
            if self.shrinks > initial_shrinks:
                return True
        return not ran_at_least_one

    def consider_new_nodes(self, nodes):
        # evaluate candidate, update shrink_target if predicate holds
        result = self.engine.cached_test_function(nodes)
        if self.predicate(result):
            self.update_shrink_target(result)
            return True
        return False

