class ParetoFront:
    def __init__(self, random: Random) -> None:
        self.front: SortedList[ConjectureResult] = SortedList(key=lambda d: sort_key(d.nodes))

    def add(self, data) -> bool:
        if data.status < Status.VALID:
            return False
        self.front.add(data)
        # Randomized clear-down: sample 10, evict dominated
        for _ in range(10):
            candidate = random.choice(self.front)
            if dominance(candidate, data) == LEFT_DOMINATES:
                self.front.remove(candidate)
        return True

def dominance(left, right, *, target):
    left_score = left.target_observations.get(target, NO_SCORE)
    right_score = right.target_observations.get(target, NO_SCORE)
    if left_score >= right_score:
        return LEFT_DOMINATES
    return RIGHT_DOMINATES

def impersonate(target):
    def accept(f):
        f.__code__ = f.__code__.replace(
            co_filename=target.__code__.co_filename,
            co_firstlineno=target.__code__.co_firstlineno,
        )
        f.__name__ = target.__name__
        f.__module__ = target.__module__
        f.__doc__ = target.__doc__
        f.__globals__["__hypothesistracebackhide__"] = True
        f.__wrapped_target = target
        return f
    return accept

def proxies(target: T) -> Callable[[Callable], T]:
    replace_sig = define_function_signature(target.__name__, target.__doc__, get_signature(target))
    def accept(proxy):
        return impersonate(target)(wraps(target)(replace_sig(proxy)))
    return accept

def consumer(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        gen = func(*args, **kwargs)
        next(gen)
        return gen
    return wrapper

def synchronized(func):
    @wraps(func)
    def inner(*args, **kwargs):
        iterator = func(*args, **kwargs)
        return serialize(iterator)
    return inner

