def callable_cached(func):
    args_flat_to_return_value = {}
    args_flat_to_exception = {}
    args_flat_to_return_value_get = args_flat_to_return_value.get

    @wraps(func)
    def _callable_cached(*args):
        args_flat = args[0] if len(args) == 1 else args
        try:
            args_hashable = hash(args_flat)
        except TypeError:
            return func(*args)  # unhashable, skip cache
        cached = args_flat_to_return_value_get(args_flat)
        if cached is not None:
            return cached
        cached_exc = args_flat_to_exception_get(args_flat)
        if cached_exc is not None:
            raise cached_exc
        try:
            result = func(*args)
        except Exception as exc:
            args_flat_to_exception[args_flat] = exc
            raise
        args_flat_to_return_value[args_flat] = result
        return result
    return _callable_cached

