def _len(self):
    if self._growing:
        start = self._start
        stop = self._stop
        step = self._step
    else:
        start = self._stop
        stop = self._start
        step = -self._step
    distance = stop - start
    if distance <= self._zero:
        return 0
    else:
        q, r = divmod(distance, step)
        return int(q) + int(r != self._zero)

