    all_validators.update(validators)
    if type_checker is None:
        type_checker = validator.TYPE_CHECKER
    if format_checker is None:
        format_checker = validator.FORMAT_CHECKER
    return create(
        meta_schema=validator.META_SCHEMA,
        validators=all_validators,
        version=version,
        type_checker=type_checker,
        format_checker=format_checker,
        id_of=validator.ID_OF,
        applicable_validators=validator._APPLICABLE_VALIDATORS,
    )

def evolve(self, **changes):
    schema = changes.setdefault("schema", self.schema)
    NewValidator = validator_for(schema, default=self.__class__)

    for (attr_name, init_name) in evolve_fields:
        if init_name not in changes:
            changes[init_name] = getattr(self, attr_name)

    return NewValidator(**changes)

def iter_errors(self, instance, _schema=None):
    # ...
    for validator, k, v in validators:
        errors = validator(self, v, instance, _schema) or ()
        for error in errors:
            error._set(validator=k, validator_value=v, instance=instance, schema=_schema, type_checker=self.TYPE_CHECKER)
            if k not in {"if", "$ref"}:
                error.schema_path.appendleft(k)
            yield error

def is_valid(self, instance):
    error = next(self.iter_errors(instance), None)
    return error is None

def validate(self, *args, **kwargs):
    for error in self.iter_errors(*args, **kwargs):
        raise error

class _Error(Exception):
    def __init__(self, message, validator=_unset, path=(), cause=None, context=(),
                 validator_value=_unset, instance=_unset, schema=_unset,
                 schema_path=(), parent=None):
        super().__init__(...)
        self.path = self.relative_path = deque(path)
        self.schema_path = self.relative_schema_path = deque(schema_path)
        self.context = list(context)
        self.parent = parent
        for error in context:
            error.parent = self

    @property
    def absolute_path(self):
        parent = self.parent
        if parent is None:
            return self.relative_path
        path = deque(self.relative_path)
        path.extendleft(reversed(parent.absolute_path))
        return path

