def _checks_drafts(name=None, draft3=None, draft4=None, draft6=None,
                     draft7=None, draft201909=None, draft202012=None, raises=()):
    draft3 = draft3 or name
    draft4 = draft4 or name
    # ... default all to name if not specified ...

    def wrap(func):
        if draft3:
            func = _draft_checkers["draft3"].checks(draft3, raises)(func)
        if draft4:
            func = _draft_checkers["draft4"].checks(draft4, raises)(func)
        # ... repeat for each draft ...
        return func
    return wrap

