class Template:
    def __init__(self, template_string, name="<string>", loader=None, ...):
        reader = _TemplateReader(name, template_string, whitespace)
        self.file = _File(self, _parse(reader, self))
        self.code = self._generate_python(loader)
        self.compiled = compile(self.code, "%s.generated.py" % name, "exec",
                                dont_inherit=True)

    def _generate_python(self, loader):
        buffer = StringIO()
        ancestors = self._get_ancestors(loader)
        ancestors.reverse()
        for ancestor in ancestors:
            ancestor.find_named_blocks(loader, named_blocks)
        writer = _CodeWriter(buffer, named_blocks, loader, ancestors[0].template)
        ancestors[0].generate(writer)
        return buffer.getvalue()

    def generate(self, **kwargs):
        namespace = {"escape": escape.xhtml_escape, ...}
        namespace.update(kwargs)
        exec_in(self.compiled, namespace)
        execute = namespace["_tt_execute"]
        return execute()

async def _execute(self, transforms, *args, **kwargs):
    try:
        result = self.prepare()
        if result is not None:
            result = await result
        if self._finished:
            return
        method = getattr(self, self.request.method.lower())
        result = method(*self.path_args, **self.path_kwargs)
        if result is not None:
            result = await result
        if self._auto_finish and not self._finished:
            self.finish()
    except Exception as e:
        self._handle_request_exception(e)

class Finish(Exception):
    """An exception that ends the request without producing an error response."""
    pass

# In _handle_request_exception:
def _handle_request_exception(self, e):
    if isinstance(e, Finish):
        if not self._finished:
            self.finish(*e.args)
        return  # no error logging, no write_error
    if isinstance(e, HTTPError):
        self.send_error(e.status_code, exc_info=sys.exc_info())
    else:
        self.send_error(500, exc_info=sys.exc_info())

class RuleRouter(Router):
    def add_rules(self, rules):
        for rule in rules:
            if isinstance(rule, (tuple, list)):
                if isinstance(rule[0], basestring_type):
                    rule = Rule(PathMatches(rule[0]), *rule[1:])
                else:
                    rule = Rule(*rule)
            self.rules.append(self.process_rule(rule))

    def find_handler(self, request, **kwargs):
        for rule in self.rules:
            target_params = rule.matcher.match(request)
            if target_params is not None:
                return self.get_target_delegate(rule.target, request, **target_params)
        return None

