def define_aliases(alias_d, cls=None):
    if cls is None:
        return functools.partial(define_aliases, alias_d)

    def make_alias(name):
        @functools.wraps(getattr(cls, name))
        def method(self, *args, **kwargs):
            return getattr(self, name)(*args, **kwargs)
        return method

    for prop, aliases in alias_d.items():
        for prefix in ['get_', 'set_']:
            if prefix + prop in vars(cls):
                for alias in aliases:
                    method = make_alias(prefix + prop)
                    method.__name__ = prefix + alias
                    method.__doc__ = f'Alias for `{prefix + prop}`.'
                    setattr(cls, prefix + alias, method)
    cls._alias_to_prop = {**preexisting_aliases, **alias_to_prop}
    return cls

def caching_module_getattr(cls):
    assert cls.__name__ == '__getattr__'
    props = {name: prop for name, prop in vars(cls).items()
             if isinstance(prop, property)}
    instance = cls()

    @functools.cache
    def __getattr__(name):
        if name in props:
            return props[name].__get__(instance)
        raise AttributeError(
            f"module {cls.__module__!r} has no attribute {name!r}")

    return __getattr__

def deprecated(since, *, message='', name='', alternative='', pending=False,
               obj_type=None, addendum='', removal=''):
    def deprecate(obj):
        if isinstance(obj, type):
            func = obj.__init__
            def finalize(wrapper, new_doc):
                obj.__init__ = functools.wraps(obj.__init__)(wrapper)
                return obj
        elif isinstance(obj, (property, classproperty)):
            class _deprecated_property(type(obj)):
                def __get__(self, instance, owner=None):
                    emit_warning()
                    return super().__get__(instance, owner)
            def finalize(_, new_doc):
                return _deprecated_property(fget=obj.fget, fset=obj.fset, fdel=obj.fdel, doc=new_doc)
        else:
            func = obj
            def finalize(wrapper, new_doc):
                wrapper = functools.wraps(func)(wrapper)
                wrapper.__doc__ = new_doc
                return wrapper

def _setattr_cm(obj, **kwargs):
    sentinel = object()
    origs = {}
    for attr in kwargs:
        orig = getattr(obj, attr, sentinel)
        if attr in obj.__dict__ or orig is sentinel:
            origs[attr] = orig
        else:
            cls_orig = getattr(type(obj), attr)
            if isinstance(cls_orig, property):
                origs[attr] = orig
            else:
                origs[attr] = sentinel
    try:
        for attr, val in kwargs.items():
            setattr(obj, attr, val)
        yield
    finally:
        for attr, orig in origs.items():
            if orig is sentinel:
                delattr(obj, attr)
            else:
                setattr(obj, attr, orig)

