bc_magic = (
    b"j2"
    + pickle.dumps(bc_version, 2)
    + pickle.dumps((sys.version_info[0] << 24) | sys.version_info[1], 2)
)

class Bucket:
    def load_bytecode(self, f: t.BinaryIO) -> None:
        magic = f.read(len(bc_magic))
        if magic != bc_magic:
            self.reset()
            return
        checksum = pickle.load(f)
        if self.checksum != checksum:
            self.reset()
            return
        try:
            self.code = marshal.load(f)
        except (EOFError, ValueError, TypeError):
            self.reset()

    def write_bytecode(self, f: t.IO[bytes]) -> None:
        if self.code is None:
            raise TypeError("can't write empty bucket")
        f.write(bc_magic)
        pickle.dump(self.checksum, f, 2)
        marshal.dump(self.code, f)

class BaseLoader:
    has_source_access = True

    def get_source(self, environment, template) -> t.Tuple[str, t.Optional[str], t.Optional[t.Callable[[], bool]]]:
        raise TemplateNotFound(template)

    @internalcode
    def load(self, environment, name, globals=None) -> "Template":
        source, filename, uptodate = self.get_source(environment, name)
        bcc = environment.bytecode_cache
        if bcc is not None:
            bucket = bcc.get_bucket(environment, name, filename, source)
            code = bucket.code
        if code is None:
            code = environment.compile(source, name, filename)
        if bcc is not None and bucket.code is None:
            bucket.code = code
            bcc.set_bucket(bucket)
        return environment.template_class.from_code(environment, code, globals, uptodate)

