class UpdateDictMixin(dict[K, V]):
    on_update: cabc.Callable[[te.Self], None] | None = None

    def setdefault(self, key, default=None):
        modified = key not in self
        rv = super().setdefault(key, default)
        if modified and self.on_update is not None:
            self.on_update(self)
        return rv

    def pop(self, key, default=_missing):
        modified = key in self
        if default is _missing:
            rv = super().pop(key)
        else:
            rv = super().pop(key, default)
        if modified and self.on_update is not None:
            self.on_update(self)
        return rv

def _always_update(f):
    def wrapper(self, *args, **kwargs):
        rv = f(self, *args, **kwargs)
        if self.on_update is not None:
            self.on_update(self)
        return rv
    return update_wrapper(wrapper, f)

class cached_property(property, t.Generic[_T]):
    def __init__(self, fget, name=None, doc=None):
        super().__init__(fget, doc=doc)
        self.__name__ = name or fget.__name__
        self.slot_name = f"_cache_{self.__name__}"

    def __set__(self, obj, value):
        if hasattr(obj, "__dict__"):
            obj.__dict__[self.__name__] = value
        else:
            setattr(obj, self.slot_name, value)

    def __get__(self, obj, type=None):
        if obj is None:
            return self
        obj_dict = getattr(obj, "__dict__", None)
        if obj_dict is not None:
            value = obj_dict.get(self.__name__, _missing)
        else:
            value = getattr(obj, self.slot_name, _missing)
        if value is _missing:
            value = self.fget(obj)
            if obj_dict is not None:
                obj.__dict__[self.__name__] = value
            else:
                setattr(obj, self.slot_name, value)
        return value

    def __delete__(self, obj):
        if hasattr(obj, "__dict__"):
            del obj.__dict__[self.__name__]
        else:
            setattr(obj, self.slot_name, _missing)

class MultiDict(TypeConversionDict[K, V]):
    def __init__(self, mapping=None):
        if mapping is None:
            super().__init__()
        elif isinstance(mapping, MultiDict):
            super().__init__((k, vs[:]) for k, vs in mapping.lists())
        elif isinstance(mapping, cabc.Mapping):
            tmp = {}
            for key, value in mapping.items():
                if isinstance(value, (list, tuple, set)):
                    value = list(value)
                else:
                    value = [value]
                tmp[key] = value
            super().__init__(tmp)
        else:
            tmp = {}
            for key, value in mapping:
                tmp.setdefault(key, []).append(value)
            super().__init__(tmp)

    def __getitem__(self, key):
        if key in self:
            lst = super().__getitem__(key)
            if len(lst) > 0:
                return lst[0]
        raise exceptions.BadRequestKeyError(key)

    def getlist(self, key, type=None, cast=None):
        # returns all values for a key

def parse(self, stream, mimetype, content_length, options=None):
    if mimetype == "multipart/form-data":
        parse_func = self._parse_multipart
    elif mimetype == "application/x-www-form-urlencoded":
        parse_func = self._parse_urlencoded
    else:
        return stream, self.cls(), self.cls()

    if options is None:
        options = {}

    try:
        return parse_func(stream, mimetype, content_length, options)
    except ValueError:
        if not self.silent:
            raise
    return stream, self.cls(), self.cls()

def get_dependant(*, path: str, call: Callable[..., Any], ...) -> Dependant:
    dependant = Dependant(call=call, name=name, path=path, ...)
    endpoint_signature = get_typed_signature(call)
    signature_params = endpoint_signature.parameters
    for param_name, param in signature_params.items():
        is_path_param = param_name in path_param_names
        param_details = analyze_param(
            param_name=param_name,
            annotation=param.annotation,
            value=param.default,
            is_path_param=is_path_param,
        )
        if param_details.depends is not None:
            sub_dependant = get_dependant(
                path=path, call=param_details.depends.dependency, ...
            )
            dependant.dependencies.append(sub_dependant)
            continue
        if add_non_field_param_to_dependency(
            param_name=param_name, type_annotation=param_details.type_annotation,
            dependant=dependant,
        ):
            continue
        assert param_details.field is not None
        if isinstance(param_details.field.field_info, params.Body):
            dependant.body_params.append(param_details.field)
        else:
            add_param_to_fields(field=param_details.field, dependant=dependant)
    return dependant

