    def restart_all(self) -> None:
        """Replaces each worker, bringing its replacement into service before retiring the old worker."""
        for idx, old_process in enumerate(self.processes):
            if self.should_exit.is_set():
                return
            new_process = Process(self.config, self.sockets)
            new_process.start()
            if not new_process.wait_until_ready(self.config.timeout_worker_healthcheck, self.should_exit):
                new_process.kill()
                new_process.join()
                if not self.should_exit.is_set():
                    logger.error(
                        f"New child process [{new_process.pid}] was not ready in time; "
                        f"keeping worker [{old_process.pid}] and aborting the restart."
                    )
                return
            old_process.terminate()
            old_process.join()
            self.processes[idx] = new_process
# keep_subprocess_alive() additionally: if process.exitcode == STARTUP_FAILURE: self.should_exit.set() (stop parent)

def emit(self, name, *args, allowed_exceptions=()):
    results = []
    listeners = sorted(self.listeners[name], key=attrgetter('priority'))
    for listener in listeners:
        try:
            results.append(listener.handler(self._app, *args))
        except allowed_exceptions: raise
        except SphinxError: raise
        except Exception as exc: ... raise ExtensionError(...) from exc
    return results

