class _DNSResolverManager:
    _instance = None
    def __new__(cls):           # singleton
        if cls._instance is None: cls._instance = super().__new__(cls); cls._instance._init()
        return cls._instance
    def _init(self):
        self._loop_data = weakref.WeakKeyDictionary[  # loop -> (resolver, WeakSet[client])
            asyncio.AbstractEventLoop, tuple[aiodns.DNSResolver, weakref.WeakSet[AsyncResolver]]]()
    def get_resolver(self, client, loop):
        if loop not in self._loop_data:
            self._loop_data[loop] = (aiodns.DNSResolver(loop=loop), weakref.WeakSet())
        resolver, client_set = self._loop_data[loop]; client_set.add(client); return resolver
    def release_resolver(self, client, loop):
        resolver, client_set = self._loop_data.get(loop, (None, set()))
        client_set.discard(client)
        if not client_set: resolver.cancel(); del self._loop_data[loop]

class CleanupContext(FrozenList[_CleanupContextCallable]):
    def __init__(self): super().__init__(); self._exits = []
    async def _on_startup(self, app):          # enter phase (startup signal)
        for cb in self:
            ctx = cb(app)
            if not isinstance(ctx, AbstractAsyncContextManager): ctx = asynccontextmanager(cb)(app)
            await ctx.__aenter__(); self._exits.append(ctx)
    async def _on_cleanup(self, app):          # exit phase (cleanup signal), reversed + error aggregation
        errors = []
        for it in reversed(self._exits):
            try: await it.__aexit__(None, None, None)
            except (Exception, asyncio.CancelledError) as exc: errors.append(exc)
        if errors: raise errors[0] if len(errors)==1 else CleanupError("Multiple errors on cleanup stage", errors)

