class MultipartReader:
    response_wrapper_cls = MultipartResponseWrapper
    multipart_reader_cls: type["MultipartReader"] | None = None   # None -> type(self)
    part_reader_cls = BodyPartReader
    async def next(self): ... await self._read_boundary(); return await self.fetch_next_part()
    async def fetch_next_part(self): headers = await self._read_headers(); return self._get_part_reader(headers)
    def _get_part_reader(self, headers):
        mimetype = parse_mimetype(headers.get(CONTENT_TYPE, ""))
        if mimetype.type == "multipart":
            cls = type(self) if self.multipart_reader_cls is None else self.multipart_reader_cls
            return cls(headers, self._content, ...)        # recursive nested reader, same stream
        return self.part_reader_cls(self._boundary, headers, self._content, ...)
